== V1__sheet.sql
-- A sheet is the unit everything else is kept under. It is created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL
);
== V2__sheet_today.sql
-- Each sheet has its own "today": every date decision and default date uses it, never the real
-- clock. It starts as the real date when the sheet is created.
ALTER TABLE sheet ADD COLUMN today DATE DEFAULT CURRENT_DATE NOT NULL;
== V3__person.sql
-- People kept on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, ignoring case and surrounding spaces. Names are kept
-- trimmed; name_key is the lower-cased name the uniqueness is enforced on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date (defaults to the sheet's
-- today) and a note (may be empty). Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim may be
-- VOID. Only OPEN and SETTLED claims count toward claimed and due totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- When a claim is opened it takes the sheet's next number (1, 2, ...): no gaps, never reused.
-- A draft has no number; voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- Settling a claim fixes its due: the amount times its person's grade rate at that moment,
-- divided by 100, rounded half up to two decimals. Later rate or grade changes do not alter it.
-- A claim with no figure fixed stays live: one not SETTLED, or settled when its grade had no rate (n/a).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(15, 2);
-- Claims settled before this change take the figure they show now.
UPDATE claim c SET settled_due = (
    SELECT ROUND(c.amount * r.pct / 100, 2)
    FROM person p JOIN rate r ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
== V10__rate_from.sql
-- A rate may carry a from-date: a grade may have several rates, one per from-date, and a claim
-- uses the one with the latest from-date on or before its date. A rate with no from-date applies
-- from the beginning of time. Rates kept before this change have none.
DROP INDEX rate_sheet_grade;
ALTER TABLE rate ADD COLUMN from_date DATE;
-- One rate per grade and from-date, an undated rate counting as one from-date of its own.
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
== V11__claim_opened_by.sql
-- A claim records who opened it; that user cannot settle it (four eyes). None while DRAFT, and
-- none for claims opened before this change.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person, raised on every save; an edit names the version it loaded and is
-- refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A statement taken of a person: their due-total at that moment (null when it was n/a), how many
-- of their claims counted then, and the sheet's today when it was taken. A person shows how many
-- statements they have had and their last one's due-total and date.
CREATE TABLE person_statement (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    due_total  DECIMAL(15, 2),
    claims     INT            NOT NULL,
    taken_on   DATE           NOT NULL,
    taken_by   VARCHAR(100)   NOT NULL
);
CREATE INDEX person_statement_person ON person_statement (person_id, id);
-- A statement binds each claim of the person that counts then to the due it shows then: the claim
-- shows and totals that figure (null: n/a) until the person's next statement rebinds it, or leaves
-- it unbound (live again) when it no longer counts. A settled claim's fixed due still wins.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
== V14__period.sql
-- The sheet's periods: a name unique on the sheet (ignoring case and surrounding spaces) and a
-- from and to date, both inclusive. No two periods of a sheet overlap. A claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V15__period_closed.sql
-- A period can be closed: its due-total is then fixed at the figure it had when it was closed
-- (later rate changes do not move it), and no claim dated inside it can be added, edited,
-- opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
== V16__person_retired.sql
-- A person can be retired from a date: they count as retired at once, whatever the date, and no
-- claim dated after it can be added for them (or moved there). Null while not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- A person can be put on hold and taken off it again: while held, their OPEN claims count in no
-- live total (their SETTLED ones still do).
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
== V18__roles_clerk_limit.sql
-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it. NULL means
-- no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2) CHECK (clerk_limit >= 0);
-- The role each user name holds on the sheet. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
== V19__sheet_floor.sql
-- The sheet's floor: a claim's live due is at least it.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
== V20__sheet_terms.sql
-- The sheet's terms: a claim is due by its date plus this many days.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL CHECK (terms >= 0);
== V21__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every
-- full 30 days it is overdue.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
== V22__person_patron.sql
-- A person's patrons: other people on the same sheet, each named at most once. A person shows
-- their patrons' names and their backing (the patrons' due-totals added up, n/a ones skipped).
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (patron_id <> person_id),
    CONSTRAINT person_patron_once UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
== V23__person_grade_dated.sql
-- A person's grade is dated: person.grade is the first grade they were given, applying from the
-- beginning of time, and each later grade is kept here from its from-date (one per from-date). A
-- claim uses the grade in force on its date: the one with the latest from-date on or before it.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE       NOT NULL,
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    PRIMARY KEY (person_id, from_date)
);
== V24__claim_corrects.sql
-- A correction is a claim with a negative amount; it names the number of the SETTLED claim of the
-- same person that it corrects (none for every other claim). The amount's unnamed CHECK (amount >= 0)
-- goes with its column, which is rebuilt to allow a negative amount, but only for a correction.
ALTER TABLE claim ADD COLUMN corrects INTEGER;
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(15, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
== V25__sheet_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds half up, one on or after it half to
-- even; null when blank, when the sheet's today is the policy date.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
== V26__period_numbering.sql
-- The sheet's period numbering from-date: while it is set and the sheet's today is on or after it,
-- a claim opened is numbered within its period (<period name>-<n>), or X-<n> when in no period;
-- null when blank (off). A claim's number, and the number a correction corrects, become text.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);
== V27__claim_pending.sql
-- A clerk settling a claim whose due is above the clerk limit sends it to PENDING, where a steward
-- approves it (SETTLED) or rejects it (back to OPEN). The status's unnamed CHECK goes with its
-- column, which is rebuilt to allow PENDING. A PENDING claim counts like an OPEN one.
ALTER TABLE claim ADD COLUMN new_status VARCHAR(10);
UPDATE claim SET new_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN new_status RENAME TO status;
ALTER TABLE claim ALTER COLUMN status SET DEFAULT 'DRAFT';
ALTER TABLE claim ALTER COLUMN status SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_status_known
    CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
== V28__claim_listed.sql
-- Where a claim is listed among its person's claims, newest first: the highest on the sheet when it
-- is added, and again when it is reassigned to another person, so a moved claim is listed as its
-- new person's newest whatever its date.
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
== V29__grade_terms_claim_due_by.sql
-- Terms set per grade: a grade without its own terms uses the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    terms    INT          NOT NULL CHECK (terms >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by is fixed when it is created: its date plus the terms of its person's grade in
-- force on that date. It does not change when the terms or the claim's date change later.
ALTER TABLE claim ADD COLUMN due_by DATE;
-- Claims created before this change take the due-by they show now.
UPDATE claim c SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = c.sheet_id), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V30__claim_log.sql
-- A claim's status log: one line per status it has had, oldest first (by id), each with the user
-- who made the change, the sheet's today then and the claim's due as computed at that moment
-- (null: n/a). Claims added before this change have no lines.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)    NOT NULL CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID')),
    by_user   VARCHAR(100)   NOT NULL,
    on_date   DATE           NOT NULL,
    due       DECIMAL(15, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, id);
CREATE INDEX claim_log_claim ON claim_log (claim_id, id);
== V31__person_hold.sql
-- A hold has a from-date and an optional to-date (null: open-ended), and a person may have several
-- over time. Only their OPEN claims dated within a hold (and not bound by a statement) are left out
-- of the live totals. A person held before keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    position  INT    NOT NULL,
    from_date DATE   NOT NULL,
    to_date   DATE,
    CHECK (to_date IS NULL OR to_date >= from_date),
    PRIMARY KEY (person_id, position)
);
INSERT INTO person_hold (person_id, position, from_date, to_date)
    SELECT id, 0, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V32__rate_to.sql
-- A rate may carry a to-date: it applies through it. A claim dated after the to-date of the rate
-- that would apply to it has no rate (n/a). Rates kept before this change have none.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
== V33__sheet_cap.sql
-- The sheet's cap: a person's due-total is at most it; null when there is none.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(15, 2) CHECK (due_cap >= 0);
== V34__period_person_total.sql
-- A closed period fixes each person's due-total for it too, at the figure it had when it was
-- closed, for every person on the sheet then (a person added later has none: 0.00). The rows go
-- when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    due_total DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V35__dated_setting.sql
-- Settings that carry a figure are dated: each value is recorded from a from-date and is in force
-- from it until the next from-date of the same key. Before every from-date a key takes the sheet's
-- starting value (floor 1.00, late percent 0.00, terms 14 days; none for the rest). A blank value
-- (no clerk limit, no cap, a grade without terms of its own) is NULL.
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- The values sheets held before this change stay in force for every date.
INSERT INTO sheet_setting SELECT id, 'floor', DATE '1900-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting SELECT id, 'terms', DATE '1900-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting SELECT id, 'late-pct', DATE '1900-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0;
INSERT INTO sheet_setting SELECT id, 'clerk-limit', DATE '1900-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting SELECT id, 'cap', DATE '1900-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting SELECT sheet_id, 'terms-' || grade, DATE '1900-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;
DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
== V36__claim_deferred.sql
-- An OPEN claim may be deferred until a date after the sheet's today: until the sheet's today
-- reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound
-- by a statement. NULL when never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V37__claim_proofs.sql
-- How many proofs a claim has: raised by one at a time while it is neither SETTLED nor VOID. A claim
-- whose due is above the sheet's proof threshold (a dated setting, none when blank) in force on its
-- date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V38__sheet_permission.sql
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen) the
-- roles that may take it, as a comma separated list. An action with no row keeps the standing
-- rule: open, settle, void and close by clerk and steward; reassign and reopen by steward.
CREATE TABLE sheet_permission (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    action    VARCHAR(20)  NOT NULL,
    roles     VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
== V39__role_viewer.sql
-- A third role, viewer: sees the sheet and changes nothing. The role's check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
== V40__sheet_grace_days.sql
-- The sheet's grace days: when its today changes, every open period whose to-date plus them is
-- before the new today is closed; null when blank (off).
ALTER TABLE sheet ADD COLUMN grace_days INTEGER;
== V41__claim_split_from.sql
-- The number of the claim a claim was split from: set on the new OPEN claim a split makes (the
-- original keeps none).
ALTER TABLE claim ADD COLUMN split_from VARCHAR(120);
== V42__person_watch.sql
-- The users watching a person, each at most once; a watch is dropped when they stop watching, so
-- the order of ids is the order the current watchers started watching.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL,
    CONSTRAINT person_watch_once UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
== V43__sheet_delegation.sql
-- A steward's role delegated to a user name for a from-date to a to-date, inclusive, by the
-- sheet's today; while the sheet's today is inside the range the user acts as a steward.
CREATE TABLE sheet_delegation (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name  VARCHAR(100) NOT NULL,
    steward    VARCHAR(100) NOT NULL,
    from_date  DATE         NOT NULL,
    to_date    DATE         NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX sheet_delegation_user ON sheet_delegation (sheet_id, user_name);
== V44__sheet_archived.sql
-- Whether a steward has archived the sheet: everything on it stays visible and every change is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V45__person_terms.sql
-- A person's own terms in days: a claim of theirs is due by its date plus them, ahead of their
-- grade's and the sheet's terms; null when they have none.
ALTER TABLE person ADD COLUMN terms INTEGER;
== V46__retired_number.sql
-- A claim number left behind when a re-dated claim moved to another period and took the next
-- number there: it is never given to a claim again.
CREATE TABLE retired_number (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_number VARCHAR(120)   NOT NULL
);
CREATE INDEX retired_number_sheet ON retired_number (sheet_id);
== V47__claim_locked_by.sql
-- The user whose open editor locks the claim for everyone else, until they save or cancel it or
-- the sheet's today changes; none while unlocked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(100);
== V48__period_soft_closed.sql
-- A period can be soft-closed: its due-total and each person's due-total for it are fixed as on a
-- close, but claims dated inside it can still be changed. A claim added while its period is
-- soft-closed is marked a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
== V49__history.sql
-- Each version of a sheet's claims, people, rates and dated settings, as a change left it, with the
-- sheet's today when the change was made: a statement taken as of a date rebuilds the sheet from the
-- last version of each made while the sheet's today was on or before that date.
CREATE TABLE history (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL,
    kind       VARCHAR(20)    NOT NULL,
    entity_id  VARCHAR(100)   NOT NULL,
    made_on    DATE           NOT NULL,
    state      CLOB           NOT NULL
);
CREATE INDEX history_entity ON history (sheet_id, kind, entity_id, id);
-- The date a statement was taken as of (its figures as they stood at the end of it); none when it
-- was taken as the sheet stood when it was taken.
ALTER TABLE person_statement ADD COLUMN as_of DATE;
== V50__sheet_entry_date.sql
-- The sheet's entry date: while set, a new claim left undated takes it instead of the sheet's
-- today; null when blank (off).
ALTER TABLE sheet ADD COLUMN entry_date DATE;
== V51__claim_reminded.sql
-- An OPEN or PENDING claim can be reminded once per sheet-today: the last day a reminder was
-- written for it. NULL when never reminded.
ALTER TABLE claim ADD COLUMN reminded DATE;
== V52__sheet_holiday.sql
-- A holiday on the sheet: a claim's due-by, as it is fixed at creation, falling on one is moved
-- to the next day that is not one. A date is on a sheet's list at most once.
CREATE TABLE sheet_holiday (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE       NOT NULL,
    UNIQUE (sheet_id, holiday_date)
);
== V54__claim_ref.sql
-- A claim's external reference: unique on its sheet, comparing without regard to case. NULL when
-- the claim has none.
ALTER TABLE claim ADD COLUMN ref VARCHAR(120);
== V55__claim_tags.sql
-- A claim's tags: lower-case, sorted and comma separated, without repeats. NULL when it has none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);

-- Every tag ever used on a sheet, kept once a claim has carried it.
CREATE TABLE sheet_tag (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag       VARCHAR(1000) NOT NULL,
    UNIQUE (sheet_id, tag)
);
== V56__void_reason.sql
-- A void reason on the sheet's list: while the list is not empty, a claim is voided only with one
-- of them. A reason is on a sheet's list at most once.
CREATE TABLE sheet_void_reason (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason    VARCHAR(200) NOT NULL,
    UNIQUE (sheet_id, reason)
);

-- The reason a VOID claim was voided with, from its sheet's list; NULL when none was given.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
== V57__claim_comment.sql
-- A claim's comments, oldest first (by id): each with the user who wrote it and the sheet's today
-- when it was written.
CREATE TABLE claim_comment (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    by_user   VARCHAR(100)   NOT NULL,
    on_date   DATE           NOT NULL,
    text      VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, id);
CREATE INDEX claim_comment_claim ON claim_comment (claim_id, id);
== V58__claim_edited_by.sql
-- The user who last edited a claim (through its form or its row's amount entry); none until
-- edited. Like its opener, that user cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(100);
== V60__claim_batch.sql
-- The bulk settle a claim was settled by (sent to PENDING counts): the sheet's batches are
-- numbered 1, 2, ... in the order they happen; none for a claim settled one at a time.
ALTER TABLE claim ADD COLUMN batch INT;
== V61__person_contact.sql
-- A person's contact, kept trimmed and lower-cased; null when they have none. No two people on a
-- sheet share one.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
== V62__person_alias.sql
-- A person's aliases, kept trimmed. An alias shares the names' uniqueness on the sheet (ignoring
-- case): it equals no name or alias of anyone on the sheet; the service enforces that, and
-- alias_key keeps one person from holding the same alias twice.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(alias)),
    PRIMARY KEY (person_id, alias)
);
CREATE UNIQUE INDEX person_alias_key ON person_alias (person_id, alias_key);
== V63__claim_template.sql
-- A claim template on the sheet: a name (at most once per sheet), the amount and note a claim made
-- from it is given. Saving a name again replaces its amount and note; claims made earlier keep theirs.
CREATE TABLE claim_template (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    amount    DECIMAL(15, 2) NOT NULL,
    note      VARCHAR(1000) NOT NULL,
    UNIQUE (sheet_id, name)
);
== V64__pool.sql
-- A pool on the sheet: a name (at most once per sheet, compared ignoring case) and its members.
CREATE TABLE pool (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL
);
CREATE INDEX pool_sheet ON pool (sheet_id, id);

-- A member of a pool: a person of the sheet (at most once per pool) with a share percent
-- (more than 0.00, at most 100.00). A person may be in several pools.
CREATE TABLE pool_member (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id    BIGINT NOT NULL REFERENCES pool (id),
    person_id  BIGINT NOT NULL REFERENCES person (id),
    share      DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100),
    UNIQUE (pool_id, person_id)
);
== V65__sheet_pot.sql
-- The sheet's pot: an amount with two decimals shared out among each balanced pool's members by
-- their shares; null when blank (none). Not dated.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(15, 2);
== V66__sheet_parent.sql
-- The sheet's parent: the id of another sheet whose rates (then its parent's, up to three levels
-- up) apply to a grade with no rate of its own in force on a date; null when blank (none). Not dated.
ALTER TABLE sheet ADD COLUMN parent VARCHAR(100);
== V67__claim_deleted.sql
-- A DRAFT claim may be DELETED: it counts nowhere, and on the sheet's today it was deleted it may
-- be restored to DRAFT. The claim's named CHECK is replaced; the status log's unnamed CHECK goes
-- with its column, which is rebuilt to allow DELETED.
ALTER TABLE claim DROP CONSTRAINT claim_status_known;
ALTER TABLE claim ADD CONSTRAINT claim_status_known
    CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));
ALTER TABLE claim_log ADD COLUMN new_status VARCHAR(10);
UPDATE claim_log SET new_status = status;
ALTER TABLE claim_log DROP COLUMN status;
ALTER TABLE claim_log ALTER COLUMN new_status RENAME TO status;
ALTER TABLE claim_log ALTER COLUMN status SET NOT NULL;
ALTER TABLE claim_log ADD CONSTRAINT claim_log_status_known
    CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));

file.content:
== V1__sheet.sql
-- A sheet is the unit everything else is kept under. It is created the first time its id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL
);
== V2__sheet_today.sql
-- Each sheet has its own "today": every date decision and default date uses it, never the real
-- clock. It starts as the real date when the sheet is created.
ALTER TABLE sheet ADD COLUMN today DATE DEFAULT CURRENT_DATE NOT NULL;
== V3__person.sql
-- People kept on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, ignoring case and surrounding spaces. Names are kept
-- trimmed; name_key is the lower-cased name the uniqueness is enforced on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date (defaults to the sheet's
-- today) and a note (may be empty). Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim may be
-- VOID. Only OPEN and SETTLED claims count toward claimed and due totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- When a claim is opened it takes the sheet's next number (1, 2, ...): no gaps, never reused.
-- A draft has no number; voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- Settling a claim fixes its due: the amount times its person's grade rate at that moment,
-- divided by 100, rounded half up to two decimals. Later rate or grade changes do not alter it.
-- A claim with no figure fixed stays live: one not SETTLED, or settled when its grade had no rate (n/a).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(15, 2);
-- Claims settled before this change take the figure they show now.
UPDATE claim c SET settled_due = (
    SELECT ROUND(c.amount * r.pct / 100, 2)
    FROM person p JOIN rate r ON r.sheet_id = p.sheet_id AND r.grade = p.grade
    WHERE p.id = c.person_id)
WHERE c.status = 'SETTLED';
== V10__rate_from.sql
-- A rate may carry a from-date: a grade may have several rates, one per from-date, and a claim
-- uses the one with the latest from-date on or before its date. A rate with no from-date applies
-- from the beginning of time. Rates kept before this change have none.
DROP INDEX rate_sheet_grade;
ALTER TABLE rate ADD COLUMN from_date DATE;
-- One rate per grade and from-date, an undated rate counting as one from-date of its own.
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
== V11__claim_opened_by.sql
-- A claim records who opened it; that user cannot settle it (four eyes). None while DRAFT, and
-- none for claims opened before this change.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person, raised on every save; an edit names the version it loaded and is
-- refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A statement taken of a person: their due-total at that moment (null when it was n/a), how many
-- of their claims counted then, and the sheet's today when it was taken. A person shows how many
-- statements they have had and their last one's due-total and date.
CREATE TABLE person_statement (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    due_total  DECIMAL(15, 2),
    claims     INT            NOT NULL,
    taken_on   DATE           NOT NULL,
    taken_by   VARCHAR(100)   NOT NULL
);
CREATE INDEX person_statement_person ON person_statement (person_id, id);
-- A statement binds each claim of the person that counts then to the due it shows then: the claim
-- shows and totals that figure (null: n/a) until the person's next statement rebinds it, or leaves
-- it unbound (live again) when it no longer counts. A settled claim's fixed due still wins.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
== V14__period.sql
-- The sheet's periods: a name unique on the sheet (ignoring case and surrounding spaces) and a
-- from and to date, both inclusive. No two periods of a sheet overlap. A claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V15__period_closed.sql
-- A period can be closed: its due-total is then fixed at the figure it had when it was closed
-- (later rate changes do not move it), and no claim dated inside it can be added, edited,
-- opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
