            BigDecimal overdue = theirs.stream()
                    .filter(c -> c.getStatus().isOpen() && late.isPast(c, p))
                    .map(c -> shownDueOf(c, p, sheetRates, floor, late, rounding))
                    .filter(Objects::nonNull)
                    .reduce(zero(), BigDecimal::add);
