                    ? PoolMember.ofPool(poolIds.get(m.getPoolId()), poolIds.get(m.getMemberPoolId()), m.getShare())
                    : new PoolMember(poolIds.get(m.getPoolId()), personIds.get(m.getPersonId()), m.getShare());
            copy.setDates(m.getFromDate(), m.getToDate());
